import {
    defineRenderOnLoadActions,
    FDO_SDK,
    FDOInterface,
    PluginMetadata,
    PluginRegistry,
} from "@anikitenko/fdo-sdk";
import { Render } from "./render";

type Inspection = {
    ok: boolean;
    error?: string;
    type?: string;
    count?: number;
    keys?: string[];
};

export default class JsonInspectorPlugin extends FDO_SDK implements FDOInterface {
    private readonly _metadata: PluginMetadata = {
        name: "JSON Inspector",
        version: "1.0.0",
        author: "AleXvWaN",
        description: "Validate and summarize pasted JSON",
        icon: "search",
    };

    get metadata(): PluginMetadata {
        return this._metadata;
    }

    init(): void {
        PluginRegistry.registerHandler("inspectJson", (data: unknown): Inspection => {
            const json = typeof data === "object" && data !== null && "json" in data
                ? (data as { json?: unknown }).json
                : undefined;
            if (typeof json !== "string" || !json.trim()) {
                return { ok: false, error: "Paste JSON to inspect." };
            }
            try {
                const value: unknown = JSON.parse(json);
                const isArray = Array.isArray(value);
                const isObject = typeof value === "object" && value !== null;
                const keys = isObject && !isArray ? Object.keys(value) : undefined;
                return {
                    ok: true,
                    type: value === null ? "null" : isArray ? "array" : typeof value,
                    count: isArray ? value.length : keys ? keys.length : 1,
                    keys,
                };
            } catch {
                return { ok: false, error: "Invalid JSON." };
            }
        });
    }

    render(): string {
        return Render();
    }

    renderOnLoad() {
        return defineRenderOnLoadActions({
            handlers: {
                inspectJson: async ({ element }) => {
                    const input = document.querySelector("[data-role=\"json-input\"]");
                    const result = document.querySelector("[data-role=\"result\"]");
                    if (!(input instanceof HTMLTextAreaElement) || !(result instanceof HTMLElement)) return;
                    const button = element instanceof HTMLButtonElement ? element : null;
                    result.dataset.state = "pending";
                    result.textContent = "Inspecting…";
                    if (button) button.disabled = true;
                    try {
                        const response = await window.createBackendReq("UI_MESSAGE", {
                            handler: "inspectJson",
                            content: { json: input.value },
                        }) as Inspection;
                        if (!response?.ok) {
                            result.dataset.state = "error";
                            result.textContent = response?.error || "Unable to inspect JSON.";
                        } else {
                            const keyText = response.keys
                                ? ` Top-level keys: ${response.keys.length ? response.keys.join(", ") : "none"}.`
                                : "";
                            result.dataset.state = "success";
                            result.textContent =
                                `Type: ${response.type}. Top-level item count: ${response.count}.${keyText}`;
                        }
                    } catch {
                        result.dataset.state = "error";
                        result.textContent = "Unable to inspect JSON.";
                    } finally {
                        if (button) button.disabled = false;
                    }
                },
            },
            bindings: [{
                selector: "[data-role=\"inspect-json\"]",
                event: "click",
                handler: "inspectJson",
            }],
        });
    }
}

new JsonInspectorPlugin();

