import { DOM } from "@anikitenko/fdo-sdk";
import css from "./styles.css";

export const Render = (): string => {
    const dom = new DOM();
    const panelClass = dom.createClassFromStyle(css.panel);
    const flowClass = dom.createClassFromStyle(css.flow);
    const actionClass = dom.createClassFromStyle(css.action);
    const resultClass = dom.createClassFromStyle(css.result);
    dom.createClassFromStyle(css["@keyframes resultIn"]);

    const title = dom.createElement("h1", {}, "JSON Inspector");
    const intro = dom.createElement("p", {}, "Paste JSON to validate it and view a top-level summary.");
    const label = dom.createElement("label", { for: "json-source" }, "JSON input");
    const input = dom.createElement("textarea", {
        id: "json-source",
        "data-role": "json-input",
        rows: "8",
        spellcheck: "false",
        placeholder: "{\"project\":\"local\",\"items\":[1,2,3]}",
    }, "");
    const action = dom.createElement("button", {
        type: "button",
        class: `pure-button ${actionClass}`,
        "data-role": "inspect-json",
    }, "Inspect JSON");
    const result = dom.createElement("div", {
        class: resultClass,
        "data-role": "result",
        "data-state": "empty",
        role: "status",
        "aria-live": "polite",
    }, "No JSON inspected yet.");
    const flow = dom.createElement("div", { class: flowClass }, label + input + action);
    return dom.renderHTML(dom.createElement("main", { class: panelClass }, title + intro + flow + result));
};

/styles.css:
.panel {
    box-sizing: border-box;
    max-width: 46rem;
    margin: 0 auto;
    padding: 1rem;
    color: #172033;
    background: #f7f8fc;
    font-family: system-ui, sans-serif;

    & h1 {
        margin: 0 0 0.25rem;
        font-size: 1.35rem;
        color: #243b75;
    }

    & p {
        margin: 0 0 0.9rem;
        color: #526078;
    }
}

.flow {
    display: grid;
    gap: 0.5rem;

    & label {
        font-weight: 700;
    }

    & textarea {
        box-sizing: border-box;
        width: 100%;
        min-height: 9rem;
        padding: 0.7rem;
        resize: vertical;
        border: 1px solid #aeb8cc;
        border-radius: 0.4rem;
        background: #fff;
        color: #172033;
        font: 0.9rem/1.45 ui-monospace, monospace;
    }
}

.action {
    justify-self: start;
    background: #3559b7;
    color: #fff;
}

.result {
    margin-top: 0.85rem;
    padding: 0.75rem;
    border-left: 4px solid #8290ad;
    border-radius: 0.3rem;
    background: #fff;
    line-height: 1.45;
    overflow-wrap: anywhere;
    animation: resultIn 140ms ease-out;

    &[data-state="pending"] { border-color: #b37a12; }
    &[data-state="success"] { border-color: #24824b; }
    &[data-state="error"] { border-color: #b83232; color: #8d2020; }

    @media (prefers-reduced-motion: reduce) {
        animation: none;
    }
}

@keyframes resultIn {
    from { opacity: 0.65; transform: translateY(2px); }
    to { opacity: 1; transform: translateY(0); }
}

