import test from "node:test";
import assert from "node:assert/strict";
import { Render } from "./render";

test("renders the JSON Inspector title", () => {
    assert.match(Render(), />JSON Inspector</);
});

test("renders the input and Inspect JSON action targets", () => {
    const html = Render();
    assert.match(html, /data-role="json-input"/);
    assert.match(html, /data-role="inspect-json"/);
    assert.match(html, />Inspect JSON</);
});

test("renders a visible empty result area", () => {
    const html = Render();
    assert.match(html, /data-role="result"/);
    assert.match(html, /No JSON inspected yet\./);
});
